import java.util.*;import java.util.zip.*;import java.io.*;import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.dexbacked.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.dexlib2.iface.instruction.*;import com.android.tools.smali.dexlib2.iface.reference.*;
public class VerifyHiddenNgUnreadEquivalence {
 static Map<String,List<String>> hooks(String apk)throws Exception{var result=new TreeMap<String,List<String>>();try(var z=new ZipFile(apk)){for(var e:Collections.list(z.entries()))if(e.getName().matches("classes[0-9]*\\.dex"))try(var in=new BufferedInputStream(z.getInputStream(e))){for(var c:DexBackedDexFile.fromInputStream(Opcodes.getDefault(),in).getClasses())for(var m:c.getMethods()){if(m.getImplementation()==null)continue;boolean found=false;for(var i:m.getImplementation().getInstructions())if(i instanceof ReferenceInstruction ref&&ref.getReference() instanceof MethodReference r&&r.getDefiningClass().equals("Lapp/morphe/extension/chmate/HiddenNgUnread;"))found=true;if(found){var instructions=VerifyAutoNgIdMenuHooks.instructions(m);instructions.add(0,"registers="+m.getImplementation().getRegisterCount());result.put(m.toString(),instructions);}}}}return result;}
 public static void main(String[] a)throws Exception{var x=hooks(a[0]);var y=hooks(a[1]);if(x.isEmpty()||!x.equals(y))throw new AssertionError("Unread hooks differ: before="+x.keySet()+" after="+y.keySet());System.out.println("PASS "+x.size()+" unread hooks identical (original instructions, registers, references and branch offsets)");}
}
